class Bitset {
    private char[] bits, flipped;
    private int size, ones;
    private boolean isFlipped;
    public Bitset(int size) {
        this.size = size; bits = new char[size]; flipped = new char[size];
        java.util.Arrays.fill(bits, '0'); java.util.Arrays.fill(flipped, '1'); ones = 0;
    }
    public void fix(int idx) {
        if (!isFlipped && bits[idx] == '0') { bits[idx] = '1'; flipped[idx] = '0'; ones++; }
        else if (isFlipped && flipped[idx] == '0') { flipped[idx] = '1'; bits[idx] = '0'; ones++; }
    }
    public void unfix(int idx) {
        if (!isFlipped && bits[idx] == '1') { bits[idx] = '0'; flipped[idx] = '1'; ones--; }
        else if (isFlipped && flipped[idx] == '1') { flipped[idx] = '0'; bits[idx] = '1'; ones--; }
    }
    public void flip() { isFlipped = !isFlipped; ones = size - ones; }
    public boolean all() { return ones == size; }
    public boolean one() { return ones > 0; }
    public int count() { return ones; }
    public String toString() { return new String(isFlipped ? flipped : bits); }
}

class Bitset {
    private boolean[] bits;
    private int size, ones;
    private boolean flipped;
    public Bitset(int size) {
        this.size = size;
        bits = new boolean[size];
        ones = 0;
        flipped = false;
    }
    private boolean getActual(int idx) {
        return flipped ? !bits[idx] : bits[idx];
    }
    public void fix(int idx) {
        if (!getActual(idx)) {
            bits[idx] = !flipped;
            ones++;
        }
    }
    public void unfix(int idx) {
        if (getActual(idx)) {
            bits[idx] = flipped;
            ones--;
        }
    }
    public void flip() {
        flipped = !flipped;
        ones = size - ones;
    }
    public boolean all() { return ones == size; }
    public boolean one() { return ones > 0; }
    public int count() { return ones; }
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < size; i++) {
            sb.append(getActual(i) ? '1' : '0');
        }
        return sb.toString();
    }
}
